query:
-- NC-3: R. Smith won D primary; Greg Murphy is R (need to verify but he was incumbent)
UPDATE house_races SET status = 'General', candidate1_name = 'R. Smith', candidate1_party = 'D'
WHERE state_code = 'NC' AND district = '3';

-- NC-4: Foushee won D primary; update status to General and add R candidate (Codiga was NC-12, need NC-4 R)
UPDATE house_races SET status = 'General'
WHERE state_code = 'NC' AND district = '4';

-- NC-6: Jefferson won D primary; update status to General
UPDATE house_races SET status = 'General'
WHERE state_code = 'NC' AND district = '6';

-- NC-7: Rouzer won R primary; update status to General
UPDATE house_races SET status = 'General'
WHERE state_code = 'NC' AND district = '7';

SELECT state_code, district, status, candidate1_name, candidate1_party, candidate2_name, candidate2_party 
FROM house_races WHERE state_code = 'NC' AND district IN ('3','4','6','7') ORDER BY CAST(district AS UNSIGNED);

